window.SB.FIRESTORE_RULES = "rules_version = '2';\n\n// Security rules for Storyboard Maker: team storyboards and client review links.\n// Paste this whole file into Firebase console → Firestore Database → Rules → Publish.\n//\n// Who can do what (team storyboards):\n// - People sign in with Google. Only team members (members/{email}) can see or open the team's\n//   storyboards. The first person to set up the team becomes its admin. Admins approve people\n//   by email. If the team has a domain set (team/settings.domain), anyone signed in with a\n//   Google account at that domain can add themselves as a member.\n// - Removing someone whose email is at the team's domain marks them \"removed\" rather than\n//   deleting them, so they can't add themselves back.\n// - One editor at a time: only the member holding a storyboard's lock can save it. Any member can\n//   take the lock (the app asks first) or release it.\n//\n// Who can do what (client review links):\n// - Only team members can create client links.\n// - Anyone with a review link can view the storyboard and all comments (no account needed;\n//   browsers sign in anonymously behind the scenes so people can edit their own comments).\n// - Nobody can list or browse reviews; you need the exact link.\n// - Commenters can edit or delete only their own comments. Whoever started a thread can delete it.\n// - Only the storyboard's owner (the app that holds the secret owner key) can update the\n//   storyboard, resolve comments, post \"Team\" replies, or delete anything.\n\nservice cloud.firestore {\n  match /databases/{database}/documents {\n\n    function signedIn() {\n      return request.auth != null;\n    }\n\n    function reviewPath(reviewId) {\n      return /databases/$(database)/documents/reviews/$(reviewId);\n    }\n\n    function isOwner(reviewId) {\n      return signedIn()\n        && exists(/databases/$(database)/documents/reviews/$(reviewId)/owners/$(request.auth.uid));\n    }\n\n    // ---------- Team: Google accounts approved by an admin ----------\n\n    function googleUser() {\n      return request.auth != null\n        && request.auth.token.firebase.sign_in_provider == 'google.com'\n        && request.auth.token.email_verified == true;\n    }\n\n    function myEmail() {\n      return request.auth.token.email.lower();\n    }\n\n    function memberPath(email) {\n      return /databases/$(database)/documents/members/$(email);\n    }\n\n    function teamPath() {\n      return /databases/$(database)/documents/team/settings;\n    }\n\n    function isMember() {\n      return googleUser()\n        && exists(memberPath(myEmail()))\n        && get(memberPath(myEmail())).data.role in ['admin', 'member'];\n    }\n\n    function isAdmin() {\n      return isMember() && get(memberPath(myEmail())).data.role == 'admin';\n    }\n\n    function validMember(email) {\n      return request.resource.data.keys().hasOnly(['email', 'role', 'name', 'addedBy', 'addedAt'])\n        && request.resource.data.email == email;\n    }\n\n    // Signed in with a Google account at the team's domain (when the team has one set).\n    function atTeamDomain() {\n      let domain = get(teamPath()).data.get('domain', '');\n      let parts = myEmail().split('@');\n      return domain is string && domain != '' && parts[parts.size() - 1] == domain;\n    }\n\n    function validTeam() {\n      let d = request.resource.data;\n      return d.keys().hasOnly(['name', 'createdBy', 'createdAt', 'domain'])\n        && d.name is string\n        && d.name.size() <= 80\n        && (!('domain' in d) || (d.domain is string\n          && d.domain.size() <= 100\n          && !(d.domain in ['gmail.com', 'googlemail.com'])));\n    }\n\n    match /team/settings {\n      allow get: if googleUser();\n      allow create: if googleUser()\n        && validTeam()\n        && request.resource.data.createdBy == request.auth.uid\n        && getAfter(memberPath(myEmail())).data.role == 'admin';\n      allow update: if isAdmin()\n        && validTeam()\n        && request.resource.data.createdBy == resource.data.createdBy;\n    }\n\n    match /members/{email} {\n      allow get: if googleUser() && (email == myEmail() || isMember());\n      allow list: if isMember();\n      // Admins approve people. The very first admin is created together with the team itself.\n      // People at the team's domain can add themselves (unless they were removed: that document\n      // still exists, so this would be an update, which only admins can make).\n      allow create: if validMember(email) && (\n        (isAdmin() && request.resource.data.role in ['admin', 'member'])\n        || (googleUser()\n          && email == myEmail()\n          && request.resource.data.role == 'admin'\n          && !exists(teamPath())\n          && getAfter(teamPath()).data.createdBy == request.auth.uid)\n        || (googleUser()\n          && email == myEmail()\n          && request.resource.data.role == 'member'\n          && exists(teamPath())\n          && atTeamDomain())\n      );\n      // Admins can't change or remove themselves, so a team can't lose its last admin by accident.\n      allow update: if isAdmin()\n        && email != myEmail()\n        && validMember(email)\n        && request.resource.data.role in ['admin', 'member', 'removed'];\n      allow delete: if isAdmin() && email != myEmail();\n    }\n\n    function holdsLock(boardId) {\n      let board = get(/databases/$(database)/documents/boards/$(boardId)).data;\n      return isMember() && board.lock != null && board.lock.uid == request.auth.uid;\n    }\n\n    match /boards/{boardId} {\n      allow read: if isMember();\n      allow create: if isMember() && request.resource.data.lock.uid == request.auth.uid;\n      allow update: if isMember() && (\n        // Taking, keeping or releasing the editing lock (the app asks before taking over).\n        (request.resource.data.diff(resource.data).affectedKeys().hasOnly(['lock'])\n          && (request.resource.data.lock == null || request.resource.data.lock.uid == request.auth.uid))\n        // Saving: only whoever holds the lock, and they keep it.\n        || (resource.data.lock != null\n          && resource.data.lock.uid == request.auth.uid\n          && request.resource.data.lock != null\n          && request.resource.data.lock.uid == request.auth.uid)\n      );\n      allow delete: if isMember() && resource.data.lock != null && resource.data.lock.uid == request.auth.uid;\n\n      match /data/{docId} {\n        allow read: if isMember();\n        allow write: if holdsLock(boardId);\n      }\n\n      match /images/{imageId} {\n        allow read: if isMember();\n        allow write: if holdsLock(boardId);\n      }\n    }\n\n    // ---------- Client review links ----------\n\n    match /reviews/{reviewId} {\n      allow get: if true;\n      allow list: if false;\n      allow create: if isMember()\n        && request.resource.data.ownerKeyHash is string\n        && request.resource.data.ownerKeyHash.size() == 64;\n      allow update: if isOwner(reviewId)\n        && request.resource.data.ownerKeyHash == resource.data.ownerKeyHash;\n      allow delete: if isOwner(reviewId);\n\n      // Proof of ownership: a browser becomes an owner by presenting the secret key whose\n      // SHA-256 hash is stored on the review. These documents are never readable by others.\n      match /owners/{uid} {\n        allow get: if signedIn() && request.auth.uid == uid;\n        allow create: if signedIn()\n          && request.auth.uid == uid\n          && request.resource.data.keys().hasOnly(['key', 'createdAt'])\n          && request.resource.data.key is string\n          && hashing.sha256(request.resource.data.key).toHexString().lower()\n             == get(reviewPath(reviewId)).data.ownerKeyHash;\n        allow delete: if signedIn() && request.auth.uid == uid;\n        allow list, update: if false;\n      }\n\n      match /images/{imageId} {\n        allow read: if true;\n        allow write: if isOwner(reviewId);\n      }\n\n      match /comments/{commentId} {\n        function validContent(d) {\n          return d.authorName is string\n            && d.authorName.size() > 0\n            && d.authorName.size() <= 80\n            && d.body is string\n            && d.body.size() <= 5000\n            && d.kind in ['comment', 'suggestion', 'reply'];\n        }\n\n        function startedThread() {\n          return resource.data.parentId is string\n            && get(/databases/$(database)/documents/reviews/$(reviewId)/comments/$(resource.data.parentId)).data.authorUid == request.auth.uid;\n        }\n\n        allow read: if true;\n\n        allow create: if signedIn()\n          && exists(reviewPath(reviewId))\n          && request.resource.data.authorUid == request.auth.uid\n          && validContent(request.resource.data)\n          && request.resource.data.status == 'open'\n          && request.resource.data.isTeam is bool\n          && (request.resource.data.isTeam == false || isOwner(reviewId));\n\n        allow update: if signedIn() && (\n          (resource.data.authorUid == request.auth.uid\n            && request.resource.data.diff(resource.data).affectedKeys()\n                 .hasOnly(['body', 'suggestion', 'updatedAt', 'edited', 'authorName'])\n            && validContent(request.resource.data))\n          || (isOwner(reviewId)\n            && request.resource.data.diff(resource.data).affectedKeys()\n                 .hasOnly(['status', 'resolvedAt', 'resolvedBy']))\n        );\n\n        allow delete: if signedIn() && (\n          resource.data.authorUid == request.auth.uid\n          || isOwner(reviewId)\n          || startedThread()\n        );\n      }\n    }\n  }\n}\n";
